<script setup lang="ts">
import { computed } from 'vue'
import { useNavigationPosition } from '@building-suit/ux'
import type { BsAccountActivityCopy, BsAccountActivityForm, BsAccountActivityView } from '../types/accountActivityPresentation'
const props = defineProps<{ copy: BsAccountActivityCopy; view: BsAccountActivityView }>()
const form = defineModel<BsAccountActivityForm>('form', { required: true })
const emit = defineEmits<{ close: []; back: []; apply: []; retry: []; page: [direction: number]; journal: [id: string, entryId: string]; account: [id: string, entryId: string] }>()
const { content, heading, remember } = useNavigationPosition(computed(() => props.view.navigationKey))
function navigate(id: string, entryId: string) { remember(`${props.view.kind}-${entryId}`); if (props.view.kind === 'account') emit('journal', id, entryId); else emit('account', id, entryId) }
</script>
<template>
 <BsDialog :visible="view.visible" :title="view.title" size="lg" @update:visible="value => { if (!value) emit('close') }"><BsStack ref="content" gap="md"><BsButton v-if="view.canBack" size="sm" @click="emit('back')"><BsIcon name="arrowRight" directional :size="16"/>{{ copy.back }}</BsButton><BsHeading ref="heading" tabindex="-1" :level="2" size="h3">{{ view.heading }}</BsHeading><BsInline wrap><BsBadge v-for="badge in view.badges" :key="badge">{{ badge }}</BsBadge></BsInline>
  <BsForm v-if="view.kind === 'account'" layout="grid" :columns="2" @submit.prevent="emit('apply')"><BsFloatingField :label="copy.from"><BsInput id="activity-from" :model-value="form.from" type="date" required :disabled="view.loading" @update:model-value="form = { ...form, from: String($event ?? '') }"/></BsFloatingField><BsFloatingField :label="copy.to"><BsInput id="activity-to" :model-value="form.to" type="date" required :min="form.from" :disabled="view.loading" @update:model-value="form = { ...form, to: String($event ?? '') }"/></BsFloatingField><BsButton type="submit" variant="primary" :disabled="view.loading || view.invalidPeriod">{{ copy.apply }}</BsButton></BsForm>
  <BsText v-if="view.error" role="alert" tone="danger">{{ view.error }} <BsButton size="sm" @click="emit('retry')">{{ copy.retry }}</BsButton></BsText><BsSectionSkeleton v-if="view.loading" variant="table" :rows="5"/>
  <template v-else-if="!view.error"><BsText v-if="view.period" size="sm" tone="muted">{{ view.period }}</BsText><BsGrid :columns="4" gap="md"><BsCard v-for="metric in view.metrics" :key="metric.id" :data-testid="`activity-${metric.id}`" variant="flat" padding="sm"><BsText size="xs" tone="muted">{{ metric.label }}</BsText><BsText emphasis="bold">{{ metric.value }}</BsText><BsText v-if="metric.side" size="xs" tone="muted">{{ metric.side }}</BsText></BsCard></BsGrid><BsText v-if="!view.rows.length" size="sm">{{ copy.empty }}</BsText>
   <BsDataTable v-else :value="view.rows" data-key="id" :label="view.title" :columns="[{ key: 'date', field: 'date', header: copy.date }, { key: 'name', header: view.kind === 'account' ? copy.description : copy.account }, { key: 'debit', field: 'debit', header: copy.debit, align: 'end' }, { key: 'credit', field: 'credit', header: copy.credit, align: 'end' }, ...(view.kind === 'account' ? [{ key: 'running', header: copy.running, align: 'end' as const }] : [])]"><template #cell-name="{ row }"><BsButton variant="link" :data-nav-id="`${view.kind}-${row.id}`" align="start" @click="navigate(row.targetId, row.id)">{{ row.name }}</BsButton><BsText v-if="row.detail" size="xs" tone="muted">{{ row.detail }}</BsText><BsText v-if="row.original" size="xs" tone="muted">{{ row.original }}</BsText></template><template #cell-running="{ row }"><BsText as="span">{{ row.running }}</BsText><BsText as="span" size="xs" tone="muted">{{ row.side }}</BsText></template></BsDataTable>
   <BsInline v-if="view.kind === 'account' && view.rows.length" as="nav" :aria-label="copy.pages" wrap justify="between"><BsButton :disabled="view.previousDisabled" size="sm" @click="emit('page', -1)">{{ copy.previous }}</BsButton><BsText>{{ view.pageLabel }}</BsText><BsButton :disabled="view.nextDisabled" size="sm" @click="emit('page', 1)">{{ copy.next }}</BsButton></BsInline><BsText v-if="view.hint" size="sm" tone="muted">{{ view.hint }}</BsText><BsDescriptionList v-if="view.totals.length" :columns="2"><BsDescriptionItem v-for="total in view.totals" :key="total.label" :term="total.label">{{ total.value }}</BsDescriptionItem></BsDescriptionList>
  </template>
 </BsStack></BsDialog>
</template>
